(function registerIlBronzaDatatablesColumnVisibility() {
	if ($.fn.dataTable && $.fn.dataTable.Api) {

		$.fn.dataTable.Api.register('manageColumnVisibility()', function (columnName, visibility, options)
		{
			let dt = this;

			options = options || {};

			// full: UI + AJAX (default) | applyOnly: column + sidebar only | persistOnly: POST only (after applyOnly batch)
			const mode = options.mode || 'full';
			const silent = !! options.silent;

			let table = this.getTableElement();
			let tableId = table.attr('id');
			let tableColumnDisplayRoute = table.data('columndisplayroute');

			let action = visibility ? 'showColumn' : 'hideColumn';

			function ajaxPersist()
			{
				var jqXHR = $.ajax({
					url: tableColumnDisplayRoute,
					dataType: 'json',
					type: 'POST',
					data: {
						columnName: columnName,
						action: action
					}
				});

				jqXHR.done(function (response)
				{
					if (! (response && response.success === true))
					{
						if (! silent && mode === 'full')
							window.addDangerNotification('Impossibile modificare la visualizzazione della colonna');
						return;
					}

					if (! silent && mode === 'full')
					{
						let aLbl = $('#togglefields' + tableId).find('[data-name="' + columnName + '"]');
						if(visibility)
							window.addSuccessNotification('Colonna "' + (aLbl.length ? aLbl.text() : columnName) + '" mostrata con successo');
						else
							window.addWarningNotification('Colonna "' + (aLbl.length ? aLbl.text() : columnName) + '" nascosta con successo');
					}
				});

				jqXHR.fail(function ()
				{
					if (! silent && mode === 'full')
						window.addDangerNotification('Impossibile modificare la visualizzazione della colonna');
				});

				return jqXHR;
			}

			if (mode === 'persistOnly')
			{
				if (! tableColumnDisplayRoute)
					return $.Deferred().resolve({ success: true }).promise();

				return ajaxPersist();
			}

			let a = $('#togglefields' + tableId).find('[data-name="' + columnName + '"]');

			let columnIndex = null;

			if (options.forceColumnIndex !== undefined && options.forceColumnIndex !== null)
			{
				const forced = parseInt(options.forceColumnIndex, 10);
				if (! isNaN(forced))
					columnIndex = forced;
			}

			if (columnIndex === null || isNaN(columnIndex))
			{
				if (a.length)
				{
					columnIndex = a.data('column');
					if (columnIndex === undefined || columnIndex === null || isNaN(columnIndex))
					{
						const rawAttr = a.attr('data-column');
						if (rawAttr !== undefined && rawAttr !== null && rawAttr !== '')
							columnIndex = parseInt(rawAttr, 10);
					}
				}
			}

			if (columnIndex === null || isNaN(columnIndex))
			{
				const byIndexToName = (window.__ibDatatableColumnIndexToFieldName || {})[tableId] || {};

				Object.keys(byIndexToName).some(function (k) {
					if (byIndexToName[k] === columnName)
					{
						columnIndex = parseInt(k, 10);
						return true;
					}
					return false;
				});
			}

			if (columnIndex === null || isNaN(columnIndex))
				return $.Deferred().resolve({ success: false }).promise();

			var column = dt.column(columnIndex);
			const summaryWasActive = !! (table[0] && table[0].__summaryActive === true);
			let summaryButton = null;

			if (summaryWasActive)
			{
				try
				{
					summaryButton = dt.button('.removesummary');
					if (summaryButton && typeof summaryButton.trigger === 'function')
						summaryButton.trigger();
				}
				catch (err) {}
			}

			column.visible( visibility );

			if (a.length)
			{
				if(visibility)
					$(a).data('visibility', 1).addClass('uk-text-bold');
				else
					$(a).data('visibility', 0).removeClass('uk-text-bold');
			}

			if (summaryWasActive && summaryButton && typeof summaryButton.trigger === 'function')
			{
				try { summaryButton.trigger(); } catch (err) {}
			}

			if (mode === 'applyOnly')
				return $.Deferred().resolve({ success: true }).promise();

			if (! tableColumnDisplayRoute)
				return $.Deferred().resolve({ success: true }).promise();

			return ajaxPersist();
		});


		$(document).ready(function($)
		{
			$('a.toggle-vis').on('click', function (e)
			{
				var that = this;
				e.preventDefault();

				var dt = $('#' + $(that).parents('ul.toggle-vis-container').data('tableid')).DataTable();

				let columnName = $(that).data('name');
				let currentVisibility = $(that).data('visibility');

				return dt.manageColumnVisibility(columnName, ! currentVisibility);
			});

			$('.filterfunctions .hidecolumn').click(function (e)
			{
				e.stopPropagation();

				let th = $(this).parents('th');
				let columnName = th.data('name');

				var dt = $('#' + $(this).parents('table').data('realid')).DataTable();

				return dt.manageColumnVisibility(columnName, false);
			});

		});
	} else {
		// Riprova dopo un attimo
		setTimeout(registerIlBronzaDatatablesColumnVisibility, 100);
	}
})();
